void DaemonSupervisor::FinishNativeShutdown() {
  loader_.reset();
  const auto browser_shutdown = peer::InspectNativeBrowserShutdown();
  if (browser_shutdown.admission_closed && browser_shutdown.phase < 6) {
    // Ordinary process shutdown must finish Profile/content/thread teardown
    // before the native parent can attest its browser writer cohort. Retain
    // the selected native owner/monitor; its late phase6 handshake owns CLEAN
    // acknowledgement and original-child reap. This is not a stopped result.
    DidFinishShutdown({false, std::nullopt});
    return;
  }

// Process shutdown flushes existing commands, preserving last-session state
// when no windows remain. It must not rebuild an empty current-window list.
void FlushPendingCommandsWithWriteCompletion(
