// Native lifetime observation only; grants no profile/storage authority.

void SessionServiceBase::FlushPendingCommandsWithWriteCompletion(
    base::OnceCallback<void(sessions::SessionWriteCompletion)> done) {
  auto report = base::BindPostTaskToCurrentDefault(std::move(done));
  if (!is_saving_enabled_ || !command_storage_manager_) {
    sessions::SessionWriteCompletion result;
    result.backend_outcomes.push_back(!is_saving_enabled_
        ? sessions::SessionBackendWriteOutcome::kSavingDisabled
        : sessions::SessionBackendWriteOutcome::kBackendUnavailable);
    std::move(report).Run(std::move(result));
    return;
  }
  command_storage_manager_->SaveWithCompletion(std::move(report));
}

